using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z0-9]{6,10}$", ErrorMessage = "Student ID must be 6–10 uppercase alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "The science of numbers, quantity, and space." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Ph.D. in Computer Science from MIT. 12 years of teaching experience specializing in introductory programming and software engineering.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Former Google engineer with a focus on distributed systems. Authored two textbooks on algorithm design.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction management, and introduction to NoSQL systems.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Database researcher with publications in VLDB and SIGMOD. Consults for enterprise data architecture projects." },
            new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Award-winning mathematics educator with 20 years at the university. Research interests in number theory.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Specialist in applied mathematics and machine learning theory. Previously at Bell Labs." },
            new() { Id = 6, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Richard Feynman Jr.", InstructorBio = "Experimental physicist specializing in optics and quantum mechanics demonstrations for undergraduates." },
            new() { Id = 7, DepartmentId = 3, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Lisa Randall", InstructorBio = "Theoretical physicist with research in particle physics and cosmology. Fellow of the American Physical Society." },
            new() { Id = 8, DepartmentId = 4, CourseCode = "ENG 110", Title = "Academic Writing", Description = "Develop college-level writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Prof. David Mitchell", InstructorBio = "Published author and writing instructor. MFA from Iowa Writers' Workshop.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 4, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, including poetry, fiction, and drama.", Credits = 3, Schedule = "TTh 1:00–2:15 PM", InstructorName = "Dr. Toni Morrison-Bell", InstructorBio = "Scholar of African-American literature with a focus on narrative theory and cultural criticism." },
            new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance, covering political, social, and cultural developments.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Howard Zhang", InstructorBio = "Historian specializing in cross-cultural exchange along ancient trade routes. Published in Journal of World History." },
            new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 205", Title = "Modern European History", Description = "Europe from the French Revolution to the present: industrialization, nationalism, world wars, and European integration.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Elena Volkov", InstructorBio = "Expert on 20th-century European political history. Formerly a visiting scholar at Oxford University." },
            new() { Id = 12, DepartmentId = 1, CourseCode = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, model evaluation, and practical applications using Python.", Credits = 3, Schedule = "TTh 3:30–4:45 PM", InstructorName = "Dr. James Park", InstructorBio = "Former Google engineer with a focus on distributed systems. Authored two textbooks on algorithm design.", IsFeatured = true }
        };

        // Link departments to courses
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

