@page "/"
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p>Explore our departments, discover courses, and enroll for the upcoming semester.</p>
        <a href="/courses" class="btn btn-primary">Browse All Courses</a>
        <a href="/enroll" class="btn btn-secondary">Enroll Now</a>
    </div>

    <section class="featured-section">
        <h2>Featured Courses</h2>
        <div class="course-grid">
            @foreach (var course in featuredCourses)
            {
                <div class="course-card">
                    <span class="badge">@course.Department?.Abbreviation</span>
                    <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                    <p class="course-code">@course.CourseCode &middot; @course.Credits credits</p>
                    <p>@course.Schedule</p>
                </div>
            }
        </div>
    </section>

    <section class="departments-section">
        <h2>Departments</h2>
        <div class="dept-grid">
            @foreach (var dept in departments)
            {
                <div class="dept-card">
                    <h3><a href="/courses?departmentId=@dept.Id">@dept.Name</a></h3>
                    <p>@dept.Description</p>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<CourseCatalog.Models.Course> featuredCourses = new();
    private List<CourseCatalog.Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@rendermode InteractiveServer
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<div class="container">
    <h1>Course Catalog</h1>

    <div class="search-controls">
        <input type="text" @bind="searchTerm" @bind:event="oninput" placeholder="Search by title, code, or instructor..." class="search-input" />
        <select @bind="selectedDepartmentId" @bind:after="OnFilterChanged" class="dept-filter">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>

    <p class="results-count">Showing @filteredCourses.Count course(s)</p>

    <div class="course-list">
        @foreach (var course in filteredCourses)
        {
            <div class="course-list-item">
                <div class="course-list-header">
                    <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                    <span class="badge">@course.CourseCode</span>
                </div>
                <p class="course-meta">@course.Department?.Name &middot; @course.Credits credits &middot; @course.Schedule</p>
                <p class="course-desc">@course.Description</p>
                <p class="course-instructor">Instructor: @course.InstructorName</p>
            </div>
        }
    </div>
</div>

@code {
    private string searchTerm = string.Empty;
    private int selectedDepartmentId;
    private List<CourseCatalog.Models.Department> departments = new();
    private List<CourseCatalog.Models.Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        ApplyFilters();
    }

    private void OnFilterChanged()
    {
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.SearchCourses(
            searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }
}

@page "/enroll"
@inject CourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>

    @if (submitted)
    {
        <div class="success-message">
            <h2>Request Submitted!</h2>
            <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseTitle</strong> has been received.</p>
            <p>You will receive a confirmation email at your university address within 2 business days.</p>
            <a href="/courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <p>Complete the form below to submit an enrollment request. All fields are required.</p>

        <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="form-group">
                <label for="studentName">Full Name</label>
                <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
                <ValidationMessage For="() => Model.StudentName" />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., ABC12345" />
                <ValidationMessage For="() => Model.StudentId" />
            </div>

            <div class="form-group">
                <label for="courseId">Course</label>
                <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-control">
                    <option value="0">-- Select a course --</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.CourseCode - @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromForm]
    private CourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<CourseCatalog.Models.Course> courses = new();
    private bool submitted;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseTitle = course?.Title ?? "Unknown Course";
        submitted = true;
    }
}

